using System;using UnityEngine;
namespace GreyHarbor {
 public static class WeaponMagazine314 {
  public static void Ensure(ItemStack gun){if(gun==null||!WeaponRules279.IsWeapon(gun.Kind))return;if(!gun.MagazineReady314){gun.Loaded314=gun.LoadedFound314=0;gun.LoadedAmmo314=WeaponRules279.GreenAmmoFor(gun.Kind);gun.MagazineReady314=true;}if(gun.Loaded314<0||gun.LoadedFound314<0||gun.LoadedFound314>gun.Loaded314||gun.Loaded314>ModRules30.Profile(gun).MagazineSize)throw new InvalidOperationException("枪械弹匣数量无效");if(!WeaponRules279.Compatible(gun.Kind,gun.LoadedAmmo314)){if(gun.Loaded314>0)throw new InvalidOperationException("枪械与已装弹药不兼容");gun.LoadedAmmo314=WeaponRules279.GreenAmmoFor(gun.Kind);}}
  public static int LoadedValue(ItemStack gun)=>gun!=null&&gun.MagazineReady314?gun.Loaded314*RaidInventory.Value(gun.LoadedAmmo314):0;
 }
 public sealed partial class RaidGame {
  public void StoreActiveMagazine314(){if(Equipped==null)return;Equipped.Loaded314=Magazine;Equipped.LoadedFound314=MagazineFound;Equipped.LoadedAmmo314=MagazineAmmo;Equipped.MagazineReady314=true;}
  public void RestoreActiveMagazine314(){if(Equipped==null){Magazine=MagazineFound=0;return;}WeaponMagazine314.Ensure(Equipped);Magazine=Equipped.Loaded314;MagazineFound=Equipped.LoadedFound314;MagazineAmmo=Equipped.LoadedAmmo314;}
  public bool CanLoadGun314(ItemArea from,int cell,ItemArea to,int gunCell){if(CorpseSource325(to)||Phase!=GamePhase.Base||!Access(from)||!Access(to))return false;var ammo=ItemAt(from,cell);var gun=ItemAt(to,gunCell);if(ammo==null||!ammo.Identified||gun==null||!gun.Identified||!WeaponRules279.IsWeapon(gun.Kind)||!WeaponRules279.Compatible(gun.Kind,ammo.Kind))return false;StoreActiveMagazine314();WeaponMagazine314.Ensure(gun);if(gun.Loaded314>=ModRules30.Profile(gun).MagazineSize&&gun.LoadedAmmo314==ammo.Kind)return false;var warehouse=CampRules.Grid(Save).Clone();if(gun.Loaded314>0&&gun.LoadedAmmo314!=ammo.Kind){if(warehouse.Add(gun.LoadedAmmo314,gun.Loaded314-gun.LoadedFound314)!=0||warehouse.Add(gun.LoadedAmmo314,gun.LoadedFound314,ItemOrigin.Certified)!=0)return false;}return true;}
  public bool LoadGun314(ItemArea from,int cell,ItemArea to,int gunCell){if(!CanLoadGun314(from,cell,to,gunCell))return false;return MutateItems(()=>{var ammo=ItemAt(from,cell);var gun=ItemAt(to,gunCell);if(ammo==null||gun==null)return false;WeaponMagazine314.Ensure(gun);var kind=ammo.Kind;string id=ammo.Id,gunId=gun.Id;bool active=gun==Equipped;
   if(gun.Loaded314>0&&gun.LoadedAmmo314!=kind){var warehouse=CampRules.Grid(Save);if(warehouse.Add(gun.LoadedAmmo314,gun.Loaded314-gun.LoadedFound314)!=0||warehouse.Add(gun.LoadedAmmo314,gun.LoadedFound314,ItemOrigin.Certified)!=0)return false;gun.Loaded314=gun.LoadedFound314=0;}
   ammo=InventoryFor(from)?.Slots.Find(p=>p.Id==id);if(ammo==null||ammo.Kind!=kind)return false;int amount=Math.Min(ModRules30.Profile(gun).MagazineSize-gun.Loaded314,ammo.Count);if(amount<=0)return false;gun.LoadedAmmo314=kind;gun.Loaded314+=amount;if(ammo.Origin!=ItemOrigin.Ordinary)gun.LoadedFound314+=amount;RemoveAmount(from,ammo,amount);if(active)RestoreActiveMagazine314();return true;
  },"弹药已装入枪械；替换弹种时旧弹药退回仓库。");}
  bool ReturnGunRoundsCarry314(ItemStack gun){if(gun==Equipped)StoreActiveMagazine314();if(gun==null||gun.Loaded314==0)return true;var rig=Chest.Clone();var bag=Bag.Clone();int left=rig.Add(gun.LoadedAmmo314,gun.Loaded314-gun.LoadedFound314);left=bag.Add(gun.LoadedAmmo314,left);if(left>0)return false;left=rig.Add(gun.LoadedAmmo314,gun.LoadedFound314,ItemOrigin.Certified);left=bag.Add(gun.LoadedAmmo314,left,ItemOrigin.Certified);if(left>0)return false;Chest=rig;Bag=bag;gun.Loaded314=gun.LoadedFound314=0;if(gun==Equipped)RestoreActiveMagazine314();return true;}
  public bool UnloadCarriedGun314(ItemArea area,int cell)=>MutateItems(()=>{var gun=ItemAt(area,cell);return Access(area)&&gun!=null&&WeaponRules279.IsWeapon(gun.Kind)&&gun.Loaded314>0&&ReturnGunRoundsCarry314(gun);},"弹药已卸到胸挂或背包。");
  public bool UnloadGun314(ItemArea area,int cell){StoreActiveMagazine314();var gun=ItemAt(area,cell);if(!Access(area)||Phase!=GamePhase.Base||gun==null||!WeaponRules279.IsWeapon(gun.Kind)||gun.Loaded314<=0)return false;return MutateItems(()=>{gun=ItemAt(area,cell);int n=gun.Loaded314,found=gun.LoadedFound314;var grid=CampRules.Grid(Save);if(grid.Add(gun.LoadedAmmo314,n-found)!=0||grid.Add(gun.LoadedAmmo314,found,ItemOrigin.Certified)!=0)return false;gun.Loaded314=gun.LoadedFound314=0;if(gun==Equipped)RestoreActiveMagazine314();return true;},"弹药已卸回仓库。");}
 }
 public static partial class CampRules {
  static void NormalizeMagazine314(BaseSave s){bool legacy=s.Version<11;if(legacy){NormalizeMagazine279(s);if(s.Weapon!=null){s.Weapon.Loaded314=s.CampMagazine;s.Weapon.LoadedFound314=s.CampMagazineFound;s.Weapon.LoadedAmmo314=s.CampMagazineAmmo;s.Weapon.MagazineReady314=true;}}
   foreach(var list in new[]{s.Warehouse,s.CampRig,s.CampBag,s.SafeItems,s.Prepared})foreach(var gun in list){WeaponMagazine314.Ensure(gun);KeyCase314.Ensure(gun);}foreach(var drop in s.CampDrops)foreach(var gun in drop.Items){WeaponMagazine314.Ensure(gun);KeyCase314.Ensure(gun);}foreach(var gun in new[]{s.Weapon,s.SecondWeapon,s.Armor,s.RigGear,s.PackGear}){WeaponMagazine314.Ensure(gun);KeyCase314.Ensure(gun);}if(s.Weapon==null)s.CampMagazine=s.CampMagazineFound=0;else{s.CampMagazine=s.Weapon.Loaded314;s.CampMagazineFound=s.Weapon.LoadedFound314;s.CampMagazineAmmo=s.Weapon.LoadedAmmo314;}
  }
 }
}
